<script setup lang="ts">
import { Head, Link, useForm } from '@inertiajs/vue3'; import { Plus, Trash2 } from '@lucide/vue'; import { computed, watch } from 'vue'; import { Button } from '@/components/ui/button'; import { Input } from '@/components/ui/input'; import { Label } from '@/components/ui/label'; type Product={id:string;name:string;dough_weight_kg:string}; type Version={id:string;label:string;effective_from:string;effective_to:string|null;yield_per_flour_kg:string;products:Product[]}; type Option={value:string;label:string}; type Person={id:string;name:string}; type Period={id:string;year:number;month:number;labor_rate:number}; const props=defineProps<{versions:Version[];people:Person[];laborMethods:Option[];periods:Period[];now:string}>(); const form=useForm({recipe_version_id:props.versions[0]?.id??'',planned_for:props.now,flour_quantity:1,labor_method:'standard_per_kg',responsible_person_id:props.people[0]?.id??'',outputs:[{compatible_product_id:props.versions[0]?.products[0]?.id??'',quantity:1}]}); const version=computed(()=>props.versions.find(item=>item.id===form.recipe_version_id)); const products=computed(()=>version.value?.products??[]); const expectedDough=computed(()=>Number(form.flour_quantity||0)*Number(version.value?.yield_per_flour_kg||0)); const plannedDough=computed(()=>form.outputs.reduce((sum,line)=>sum+Number(line.quantity||0)*Number(products.value.find(p=>p.id===line.compatible_product_id)?.dough_weight_kg||0),0)); const period=computed(()=>{const date=new Date(form.planned_for);return props.periods.find(p=>p.year===date.getFullYear()&&p.month===date.getMonth()+1)}); watch(()=>form.recipe_version_id,()=>{form.outputs=[{compatible_product_id:products.value[0]?.id??'',quantity:1}]}); const add=()=>form.outputs.push({compatible_product_id:products.value[0]?.id??'',quantity:1});
</script><template><Head title="Planear producción" /><main class="flex flex-1 flex-col gap-5 p-4 md:p-6"><header><h1 class="text-2xl font-semibold">Planear producción</h1><p class="text-sm text-muted-foreground">Indica la harina requerida y cómo se distribuirá la masa esperada.</p></header><form class="grid gap-6" @submit.prevent="form.post('/production')"><section class="grid gap-4 rounded-xl border bg-card p-5 md:grid-cols-3"><div class="grid gap-2"><Label>Receta y versión</Label><select v-model="form.recipe_version_id" class="h-9 rounded-md border bg-transparent px-3 text-sm"><option v-for="item in versions" :key="item.id" :value="item.id">{{ item.label }}</option></select></div><div class="grid gap-2"><Label>Fecha planeada</Label><Input v-model="form.planned_for" type="datetime-local" /></div><div class="grid gap-2"><Label>Harina en kg</Label><Input v-model.number="form.flour_quantity" type="number" min="0.000001" step="0.000001" /></div><div class="grid gap-2"><Label>Responsable</Label><select v-model="form.responsible_person_id" class="h-9 rounded-md border bg-transparent px-3 text-sm"><option v-for="person in people" :key="person.id" :value="person.id">{{ person.name }}</option></select></div><div class="grid gap-2"><Label>Método de mano de obra</Label><select v-model="form.labor_method" class="h-9 rounded-md border bg-transparent px-3 text-sm"><option v-for="method in laborMethods" :key="method.value" :value="method.value">{{ method.label }}</option></select></div><div class="rounded-lg bg-muted/40 p-3 text-sm"><p>Masa esperada: <strong>{{ expectedDough.toFixed(3) }} kg</strong></p><p>Periodo: <strong>{{ period?`${period.year}-${String(period.month).padStart(2,'0')}`:'No disponible' }}</strong></p><Link v-if="period&&form.labor_method==='standard_per_kg'&&period.labor_rate<=0" :href="`/cost-periods/${period.id}/labor-rate/edit`" class="text-xs font-semibold text-amber-700 underline">Configurar mano de obra</Link></div></section><section class="grid gap-3"><div class="flex justify-between"><div><h2 class="font-semibold">Productos planeados</h2><p class="text-xs text-muted-foreground">Masa asignada {{ plannedDough.toFixed(3) }} / {{ expectedDough.toFixed(3) }} kg.</p></div><Button type="button" variant="outline" size="sm" @click="add"><Plus /> Producto</Button></div><div v-for="(line,index) in form.outputs" :key="index" class="grid items-end gap-3 rounded-lg border p-3 md:grid-cols-[1fr_12rem_auto]"><div class="grid gap-2"><Label>Producto</Label><select v-model="line.compatible_product_id" class="h-9 rounded-md border bg-transparent px-3 text-sm"><option v-for="product in products" :key="product.id" :value="product.id">{{ product.name }} · {{ product.dough_weight_kg }} kg masa/und</option></select></div><div class="grid gap-2"><Label>Cantidad</Label><Input v-model.number="line.quantity" type="number" min="0.000001" step="0.000001" /></div><Button type="button" variant="ghost" size="icon" :disabled="form.outputs.length===1" @click="form.outputs.splice(index,1)"><Trash2 /></Button></div></section><p v-if="!period" class="text-sm text-destructive">Debes abrir el periodo de costos correspondiente antes de planear esta producción.</p><p v-if="plannedDough>expectedDough" class="text-sm text-destructive">Los productos requieren más masa que el rendimiento esperado.</p><p v-if="Object.keys(form.errors).length" class="text-sm text-destructive">{{ Object.values(form.errors)[0] }}</p><div class="flex justify-end gap-2"><Button variant="outline" as-child><Link href="/production">Cancelar</Link></Button><Button type="submit" :disabled="form.processing||!period||plannedDough>expectedDough">Guardar planeación</Button></div></form></main></template>
